mapper.select:
SELECT id, user_id, slot_name, option_value, preference_type, confidence, expires_at, created_at, updated_at
FROM diet_user_preference
WHERE user_id = #{userId}
AND slot_name = #{slotName}
AND option_value = #{optionValue}
AND preference_type = #{preferenceType}

mapper.delete:
DELETE FROM diet_user_preference
WHERE id = #{id}
AND user_id = #{userId}
